/** Bundled technology logos, keyed by the `icon` field the backend sends.
 *
 * Generated once from Simple Icons (most logos) and Devicon (Java, C#,
 * Azure and Matplotlib, which Simple Icons no longer carries), so the site
 * never fetches a logo from a third-party CDN at runtime. Single-colour
 * logos carry one colour per theme, adjusted for contrast against the chip
 * background (4.5:1 in dark mode, 3:1 in light mode); multi-colour logos
 * are kept as drawn. */

export interface IconPath {
  d: string
  dark: string
  light: string
}

export type TechIcon = { viewBox: string; paths: IconPath[] } | { viewBox: string; markup: string }

